#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct SetScriptParams {
    ///Every Lua source to load, run in order. They replace all the scripts loaded before. An empty list unloads them.
    pub scripts: Option<Vec<SetScriptParamsScripts>>,
}
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct SetScriptParamsScripts {
    ///A file name to show in error messages and diagnostics, such as init.lua.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub name: Option<String>,
    ///The Lua code.
    pub source: String,
}
